INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4022915',2159,69,'P2','Contabilidade Geral - Índices de Atividade (Rotação)','Instituto AOCP - Tec Port (CODERN)/CODERN/Assistente Administrativo/Operações Portuárias/2026','Caderno Contabilidade Geral Parte 3','Considere que uma empresa registrou, em determinado exercício, receita total de vendas de R$ 4.562.500, sendo 20% realizadas à vista. Além disso, apresentou um saldo médio de contas a receber de R$ 365.000. Considerando um ano comercial de 365 dias, assinale a alternativa correta.','[["A","O giro de contas a receber é de 10 vezes ao ano, o prazo médio de recebimento é de 36,5 dias, e esse indicador demonstra, em média, em quantos dias a empresa recebe suas vendas a prazo."],["B","O giro de contas a receber é de 8 vezes ao ano, o prazo médio de recebimento é superior a 45 dias, e esse indicador demonstra o tempo médio de pagamento das obrigações da empresa."],["C","O giro de contas a receber é de 10 vezes ao ano, o prazo médio de recebimento é de 36,5 dias, e quanto maior o giro, maior tende a ser o prazo médio de recebimento."],["D","O giro de contas a receber é de 12 vezes ao ano, o prazo médio de recebimento é inferior a 30 dias, e esse indicador representa o tempo médio de estocagem."],["E","O giro de contas a receber é de 5 vezes ao ano, o prazo médio de recebimento é superior a 70 dias, e esse indicador mede a capacidade de pagamento de curto prazo da empresa."]]'::jsonb,'A',2026,500,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Atividade (Rotação).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — O giro de contas a receber é de 10 vezes ao ano, o prazo médio de recebimento é de 36,5 dias, e esse indicador demonstra, em média, em quantos dias a empresa recebe suas vendas a prazo.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Atividade (Rotação)"}'::jsonb,'Considere que uma empresa registrou, em determinado exercício, receita total de vendas de R$ 4.562.500, sendo 20% realizadas à vista. Além disso, apresentou um saldo médio de contas a receber de R$ 365.000. Considerando um ano comercial de 365 dias, assinale a alternativa corr...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
