INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3678456',2161,69,'P2','Contabilidade Geral - Índices de Atividade (Rotação)','Instituto Darwin - Cont (CREA PB)/CREA PB/2025','Caderno Contabilidade Geral Parte 3','A importância de conhecer o Prazo Médio de Rotação de Estoques (PMRE), também conhecido como Prazo Médio de Renovação ou, simplesmente, Rotação de Estoque, é fundamental na gestão financeira e operacional de qualquer empresa. Ele mede o tempo médio que a empresa leva para renovar seu estoque, ou seja, quantos dias o produto fica armazenado até ser vendido. Tomando como base essa definição e sabendo que a empresa Espertos S/A apresentou os seguintes dados contábeis do encerramento do exercício de 2024, aponte o PMRE aproximado da empresa: • Vendas do estoque – R$ 353.000,00 • Estoques em 2024 – R$ 250.000,00 • Estoques em 2023 – R$ 210.000,00 • CMV – R$ 200.000,00 • Depreciação – R$ 30.000,00 • Fornecedores – R$ 100.000,00 • Clientes – R$ 150.000,00 • Dias do período – 360','[["A","221"],["B","144"],["C","414"],["D","234"],["E","31"]]'::jsonb,'C',2025,502,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Atividade (Rotação).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — 414","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Atividade (Rotação)"}'::jsonb,'A importância de conhecer o Prazo Médio de Rotação de Estoques (PMRE), também conhecido como Prazo Médio de Renovação ou, simplesmente, Rotação de Estoque, é fundamental na gestão financeira e operacional de qualquer empresa. Ele mede o tempo médio que a empresa leva para reno...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
