INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3918164',2167,69,'P2','Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros','FUNDEPES COPEVE-UFAL - PEBTT (IF AL)/IF AL/Contabilidade/2026','Caderno Contabilidade Geral Parte 3','A empresa Barro Duro apresenta as informações contábeis ao longo do exercício: estoque inicial = R$ 250.000,00; estoque final = R$ 150.000,00; CMV = R$ 500.000,00. Sabendo-se que a rotatividade de estoques indica quantas vezes o estoque médio foi renovado ao longo do exercício, relacionando o Custo das Mercadorias Vendidas com o estoque médio, assinale a alternativa correta que representa o giro de estoque dessa empresa.','[["A","1,8 vez no período."],["B","2,5 vezes no período."],["C","3,2 vezes no período."],["D","4,0 vezes no período."],["E","5,0 vezes no período."]]'::jsonb,'B',2026,512,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — 2,5 vezes no período.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros"}'::jsonb,'A empresa Barro Duro apresenta as informações contábeis ao longo do exercício: estoque inicial = R$ 250.000,00; estoque final = R$ 150.000,00; CMV = R$ 500.000,00. Sabendo-se que a rotatividade de estoques indica quantas vezes o estoque médio foi renovado ao longo do exercício...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3735711',2168,69,'P2','Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros','FGV - AEC (CGE SP)/CGE SP/Contabilidade Pública e Finanças/2025','Caderno Contabilidade Geral Parte 3','O Auditor Estadual de Controle analisou a situação econômico-financeira do Município Alfa, com base nas demonstrações contábeis de 2024. Na ocasião, ele constatou que o Município possui os seguintes valores: Contas Valor (R$ mil) Ativo Total 1.000 Passivo Circulante 200 Passivo Não Circulante 300 Patrimônio Líquido 500 Caixa e Equivalente de Caixa 100 Resultado Operacional antes dos 160 Juros (EBITDA) Com base nessas informações, quanto aos principais indicadores de endividamento e sua interpretação, assinale a afirmativa correta.','[["A","Endividamento Geral = 0,50; Composição do Endividamento = 0,40; Dívida Líquida/EBITDA = 2,5x. O Município apresenta estrutura de capital equilibrada, com metade dos ativos financiada por recursos de terceiros e geração operacional suficiente para honrar as obrigações em até três exercícios."],["B","Endividamento Geral = 0,70; Composição do Endividamento = 0,60; Dívida Líquida/EBITDA = 3,5x. O Município demonstra alta dependência de capital externo e reduzida capacidade de pagamento, com risco elevado no curto prazo."],["C","Endividamento Geral = 0,50; Composição do Endividamento = 0,20; Dívida Líquida/EBITDA = 1,0x. O Município revela baixo endividamento, predominância de dívidas de longo prazo e liquidez operacional imediata, caracterizando folga financeira acima do ideal."],["D","Endividamento Geral = 0,40; Composição do Endividamento = 0,50; Dívida Líquida/EBITDA = 2,5x. O Município possui baixa dependência de dívidas, mas concentração significativa de obrigações de curto prazo, o que eleva o risco de liquidez."],["E","Endividamento Geral = 0,55; Composição do Endividamento = 0,45; Dívida Líquida/EBITDA = 2,0x. O Município evidencia grau moderado de endividamento e boa capacidade de pagamento, embora com tendência de aumento da exposição financeira."]]'::jsonb,'A',2025,513,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Endividamento Geral = 0,50; Composição do Endividamento = 0,40; Dívida Líquida/EBITDA = 2,5x. O Município apresenta estrutura de capital equilibrada, com metade dos ativos financiada por recursos de terceiros e geração operacional suficiente para honrar as obrigações em até três exercícios.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros"}'::jsonb,'O Auditor Estadual de Controle analisou a situação econômico-financeira do Município Alfa, com base nas demonstrações contábeis de 2024. Na ocasião, ele constatou que o Município possui os seguintes valores: Contas Valor (R$ mil) Ativo Total 1.000 Passivo Circulante 200 Passiv...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EX