INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3692508',2169,69,'P2','Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros','Unifil - Tec Cont (Pref Mandirituba)/Pref Mandirituba/2025','Caderno Contabilidade Geral Parte 3','Índice e coeficientes são medidas matemáticas utilizadas para expressar relações entre variáveis. Sobre índices e coeficientes, informe se é verdadeiro (V) ou falso (F) para o que se afirma e assinale a alternativa com a sequência correta. ( ) Índice de Endividamento indica o grau de dependência da empresa em relação a recursos de terceiros e como esses recursos estão estruturados. ( ) Análise Horizontal mostra a evolução de uma conta ou grupo de contas ao longo em um mesmo período, apresentando variação percentual ou estatística. ( ) Índice de Liquidez avalia a capacidade da empresa de quitar suas obrigações de curto e longo prazo com seus ativos. ( ) Análise Vertical mostra o percentual de participação de uma conta em relação ao total do grupo a que pertence ou a outro grupo de vários períodos diferentes.','[["A","V – F – V – V."],["B","F – F – V – V."],["C","V – F – V – F."],["D","F – V – F – V."],["E","V – V – V – V."]]'::jsonb,'C',2025,514,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — V – F – V – F.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros"}'::jsonb,'Índice e coeficientes são medidas matemáticas utilizadas para expressar relações entre variáveis. Sobre índices e coeficientes, informe se é verdadeiro (V) ou falso (F) para o que se afirma e assinale a alternativa com a sequência correta. ( ) Índice de Endividamento indica o ...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
