020.000 Passivo Circulante (PC) 300.000 Passivo Não Circulante (PNC) 500.000 Patrimônio Líquido (PL) 700.000 Receita Líquida de Vendas 1.800.000 Lucro Líquido 180.000 Lucro Operaci...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3735226',2171,69,'P2','Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros','IESES - Ana PO (MSGÁS)/MSGÁS/Contabilidade/2025','Caderno Contabilidade Geral Parte 3','Em relação à análise de índices econômicos e financeiros, verifique as afirmativas abaixo e indique a sequência correta de “V” para as verdadeiras e “F” para as falsas: ( ) A rentabilidade do ativo apresenta a relação entre os lucros ou prejuízos líquidos gerados em um ano e os ativos totais disponíveis na empresa. ( ) A margem líquida demonstra a eficiência da empresa em converter receitas em lucros e, eventualmente, em prejuízos. Permite apurar a lucratividade do negócio como um todo. ( ) A liquidez imediata apresenta a relação entre os ativos circulantes e os passivos circulantes, que constituem o capital de giro da empresa. ( ) A composição do endividamento permite perceber quanto dos ativos são provenientes de capitais de terceiros, indica o grau de comprometimento do ativo com as dívidas existentes na data do Balanço.','[["A","F, F, V, V."],["B","V, V, F, F."],["C","V, F, F, V."],["D","V, F, V, F."]]'::jsonb,'B',2025,516,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — V, V, F, F.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Questões Mescladas de Índices e Quocientes Financeiros"}'::jsonb,'Em relação à análise de índices econômicos e financeiros, verifique as afirmativas abaixo e indique a sequência correta de “V” para as verdadeiras e “F” para as falsas: ( ) A rentabilidade do ativo apresenta a relação entre os lucros ou prejuízos líquidos gerados em um ano e o...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
