INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3132881',2191,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Princípios da Contabilidade Pública','FAFIPA - Aud Int (Pref Londrina)/Pref Londrina/Serviço de Auditoria Institucional/2015','Caderno Contabilidade Pública Parte 4','Segundo os princípios de contabilidade sob a perspectiva do setor público: O Princípio da Continuidade reconhece o Patrimônio como objeto da Contabilidade e afirma a autonomia patrimonial, a necessidade da diferenciação de um Patrimônio particular no universo dos patrimônios existentes, independentemente de pertencer a uma pessoa, a um conjunto de pessoas, a uma sociedade ou a uma instituição de qualquer natureza ou finalidade, com ou sem fins lucrativos. Certo Errado','[]'::jsonb,'E',2015,616,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Princípios da Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Princípios da Contabilidade Pública"}'::jsonb,'Segundo os princípios de contabilidade sob a perspectiva do setor público: O Princípio da Continuidade reconhece o Patrimônio como objeto da Contabilidade e afirma a autonomia patrimonial, a necessidade da diferenciação de um Patrimônio particular no universo dos patrimônios existentes, independentemente de pertencer a uma pessoa, a um conjunto de pessoas, a uma sociedade ou a ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3132886',2192,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Princípios da Contabilidade Pública','FAFIPA - Aud Int (Pref Londrina)/Pref Londrina/Serviço de Auditoria Institucional/2015','Caderno Contabilidade Pública Parte 4','Segundo os princípios de contabilidade sob a perspectiva do setor público: O Princípio da Prudência determina a adoção do maior valor para os componentes do ativo e do menor para os do passivo, sempre que se apresentem alternativas igualmente válidas para a quantificação das mutações patrimoniais que alterem o patrimônio líquido. Certo Errado','[]'::jsonb,'E',2015,617,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Princípios da Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Princípios da Contabilidade Pública"}'::jsonb,'Segundo os princípios de contabilidade sob a perspectiva do setor público: O Princípio da Prudência determina a adoção do maior valor para os componentes do ativo e do menor para os do passivo, sempre que se apresentem alternativas igualmente válidas para a quantificação das mutações patrimoniais que alterem o patrimônio líquido. Certo Errado') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3876850',2193,86,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','FAFIPA - Cont (COMESP)/COMESP/2026','Caderno Contabilidade Pública Parte 4','À luz da NBC TSP - Estrutura Conceitual para Elaboração e Divulgação de Informação Contábil de Propósito Geral pelas Entidades do Setor Público, avalie as afirmativas a seguir sobre os critérios de mensuração de ativos e passivos. I. O custo histórico é uma base de mensuração que reflete o valor de entrada específico para a entidade, sendo geralmente observável e apropriado para avaliações da capacidade financeira quando os valores de saída atuais diferem significativamente. II. O valor de mercado, quando aplicado em mercados abertos, ativos e organizados, é considerado uma base que atende satisfatoriamente às características qualitativas, como relevância, representação fidedigna e verificabilidade. III. O custo de reposição ou substituição é uma base de mensuração que se baseia no valor de saída e é especialmente útil para avaliações da capacidade financeira da entidade, por refletir o montante que poderia ser obtido com a venda do ativo. Está CORRETO o que se afirma em:','[["A","I, II e III."],["B","I e II, apenas."],["C","I, apenas."],["D","II, apenas."],["E","II e III, apenas."]]'::jsonb,'D',2026,618,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — II, apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'À luz da NBC TSP - Estrutura Conceitual para Elaboração e Divulgação de Informação Contábil de Propósito Geral pelas Entidades do Setor Público, avalie as afirmativas a seguir sobre os critérios de mensuração de ativos e passivos. I. O custo histórico é uma base de mensuração que reflete o valor de entrada específico para a entidade, sendo geralmente observável e apropriado par') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3708649',2194,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','FAFIPA - Cont (CM Pinhais)/CM Pinhais/2025','Caderno Contabilidade Pública Parte 4','No nível de estrutura conceitual, não é possível identificar uma única base de mensuração que melhor atenda ao objetivo da mensuração. Portanto, a estrutura conceitual não propõe uma única base de mensuração (ou a combinação de bases de mensuração) para todas as transações, eventos econdições. A estrutura conceitual fornece orientação na seleção da base de mensuração para ativos e passivos. Considerando as disposições da NBC TSP Estrutura Conceitual sobre o Custo Histórico para a mensuração de ativos, assinale a alternativa INCORRETA.','[["A","Custo histórico de um ativo é a importância fornecida para se adquirir ou desenvolver um ativo, o qual corresponde ao caixa ou equivalentes de caixa ou ovalor de outra importância fornecida à época de sua aquisição ou desenvolvimento."],["B","No modelo do custo histórico, o montante do ativo pode ser reduzido ao se reconhecer a redução ao valor recuperável."],["C","Caso o ativo tenha sido adquirido em transação com contra prestação, o custo histórico fornece informação sobre os recursos disponíveis para a prestaçãode serviços no futuro, baseada no seu custo de aquisição."],["D","Na medida em que o custo dos serviços é evidenciado utilizando-se preços passados, a informação fornecida pelo custo histórico irá facilitar aavaliação do custo futuro de prestação de serviços caso as mudanças no valor cumulativo desde a sua aquisição sejam significativas."],["E","Quando o custo histórico for utilizado, o custo dos serviços reflete o montante dos recursos gastos para se adquirir ou desenvolver ativos consumidos na prestação de serviços."]]'::jsonb,'D',2025,619,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Na medida em que o custo dos serviços é evidenciado utilizando-se preços passados, a informação fornecida pelo custo histórico irá facilitar aavaliação do custo futuro de prestação de serviços caso as mudanças no valor cumulativo desde a sua aquisição sejam significativas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'No nível de estrutura conceitual, não é possível identificar uma única base de mensuração que melhor atenda ao objetivo da mensuração. Portanto, a estrutura conceitual não propõe uma única base de mensuração (ou a combinação de bases de mensuração) para todas as transações, eventos econdições. A estrutura conceitual fornece orientação na seleção da base de mensuração para ativo') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3708655',2195,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','FAFIPA - Cont (CM Pinhais)/CM Pinhais/2025','Caderno Contabilidade Pública Parte 4','Considerando as disposições da NBC TSP Estrutura Conceitual sobre as bases de mensuração de passivos, analise as afirmativas a seguir. I. No modelo do Custo Histórico, as mensurações iniciais podem ser ajustadas para refletir fatores como o acúmulo de juros, o acréscimo de descontos ou a amortização de prêmio. II. Custo de Liberação corresponde aos custos nos quais a entidade incorre no cumprimento das obrigações representadas pelo passivo, assumindo que o faz da maneira menos onerosa. III. O Custo de Cumprimento da obrigação se refere ao montante que corresponde à baixa imediata da obrigação. IV. O Custo de Liberação é o termo utilizado no contexto dos passivos para se referir ao mesmo conceito de preço líquido de venda utilizado no contexto dos ativos. Está CORRETO o que se afirma em:','[["A","I e IV, apenas."],["B","II e IV, apenas."],["C","II e III, apenas."],["D","I e III, apenas."],["E","I e II, apenas."]]'::jsonb,'A',2025,620,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — I e IV, apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'Considerando as disposições da NBC TSP Estrutura Conceitual sobre as bases de mensuração de passivos, analise as afirmativas a seguir. I. No modelo do Custo Histórico, as mensurações iniciais podem ser ajustadas para refletir fatores como o acúmulo de juros, o acréscimo de descontos ou a amortização de prêmio. II. Custo de Liberação corresponde aos custos nos quais a entidade i') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3423395',2196,84,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','FAFIPA - Cont (CM Paiçandu)/CM Paiçandu/2024','Caderno Contabilidade Pública Parte 4','Mensuração é o processo que consiste em determinar os valores pelos quais os elementos das demonstrações contábeis devem ser reconhecidos e apresentados nas demonstrações contábeis. Considerando as bases de mensuração de ativos previstas no Manual de Contabilidade Aplicada ao Setor Público (MCASP), assinale a alternativa CORRETA.','[["A","Custo histórico é o montante pelo qual um ativo pode ser trocado entre partes cientes e dispostas, em transação sob condições normais de mercado."],["B","Valor de mercado é o valor para se adquirir ou desenvolver um ativo, o qual corresponde ao caixa ou equivalentes de caixa ou o valor de outra importância fornecida à época de sua aquisição ou desenvolvimento."],["C","Preço líquido de venda é o custo mais econômico exigido para a entidade substituir o potencial de serviços de ativo na data do relatório."],["D","Valor em uso é o valor presente, para a entidade, do potencial de serviços ou da capacidade de gerar benefícios econômicos remanescentes do ativo, caso este continue a ser utilizado, e do valor líquido que a entidade receberá pela sua alienação ao final da sua vida útil."]]'::jsonb,'D',2024,621,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Valor em uso é o valor presente, para a entidade, do potencial de serviços ou da capacidade de gerar benefícios econômicos remanescentes do ativo, caso este continue a ser utilizado, e do valor líquido que a entidade receberá pela sua alienação ao final da sua vida útil.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'Mensuração é o processo que consiste em determinar os valores pelos quais os elementos das demonstrações contábeis devem ser reconhecidos e apresentados nas demonstrações contábeis. Considerando as bases de mensuração de ativos previstas no Manual de Contabilidade Aplicada ao Setor Público (MCASP), assinale a alternativa CORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3423396',2197,84,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','FAFIPA - Cont (CM Paiçandu)/CM Paiçandu/2024','Caderno Contabilidade Pública Parte 4','De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP), o objetivo da mensuração é selecionar bases que reflitam de modo mais adequado o custo dos serviços, a capacidade operacional e a capacidade financeira da entidade de forma que seja útil para a prestação de contas e responsabilização (accountability) e tomada de decisão. Considerando as bases de mensuração de passivos prevista no MCASP, assinale a alternativa CORRETA.','[["A","Custo de liberação é o montante que o credor aceita no cumprimento da sua demanda, ou que terceiros cobrariam para aceitar a transferência do passivo do devedor."],["B","Custo histórico é o custo no qual a entidade incorre no cumprimento das obrigações representadas pelo passivo, assumindo que o faz da maneira menos onerosa."],["C","Preço Presumido é o montante pelo qual um passivo pode ser liquidado entre partes cientes e interessadas em transação sob condições normais de mercado."],["D","Custo de cumprimento da obrigação é o montante que corresponde à baixa imediata da obrigação."]]'::jsonb,'A',2024,622,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Custo de liberação é o montante que o credor aceita no cumprimento da sua demanda, ou que terceiros cobrariam para aceitar a transferência do passivo do devedor.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP), o objetivo da mensuração é selecionar bases que reflitam de modo mais adequado o custo dos serviços, a capacidade operacional e a capacidade financeira da entidade de forma que seja útil para a prestação de contas e responsabilização (accountability) e tomada de decisão. Considerando as bases de mensuraç') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2153500',2198,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','FAFIPA - Cont (CISA AMERIOS)/CISA AMERIOS/2022','Caderno Contabilidade Pública Parte 4','De acordo com Manual de Contabilidade Aplicado ao Setor Público (MCASP), os ativos devem ser mensurados pelas seguintes bases de mensuração: Base de mensuração Entrada ou saída Observável, ou não, no mercado Específica, ou não, à entidade Entrada e Saída Observável Não específica para a entidade Saída Não observável Específica para a entidade Entrada Geralmente observável Específica para a entidade Entrada Observável Específica para a entidade Saída Observável Específica para a entidade Saída Depende da técnica de atribuição de valor Depende da técnica de atribuição de valor Identifique a base de mensuração apresentada a seguir que está relacionada com as características da transação no quadro acima: I. Custo histórico. II. Valor de mercado (quando o mercado é aberto, ativo e organizado). III. Valor de mercado (em mercado inativo). IV. Custo de reposição ou substituição. V. Preço líquido de venda. VI. Valor em uso. A sequência CORRETA, de cima para baixo, é:','[["A","I, II, VI, V, III e IV."],["B","IV, II, V, VI, III e I."],["C","I, III, V, VI, II e IV."],["D","II, VI, I, IV, V e III."],["E","IV, II, VI, V, III e I."]]'::jsonb,'D',2022,623,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — II, VI, I, IV, V e III.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'De acordo com Manual de Contabilidade Aplicado ao Setor Público (MCASP), os ativos devem ser mensurados pelas seguintes bases de mensuração: Base de mensuração Entrada ou saída Observável, ou não, no mercado Específica, ou não, à entidade Entrada e Saída Observável Não específica para a entidade Saída Não observável Específica para a entidade Entrada Geralmente observável Espec') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1054349',2199,82,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','FAFIPA - Cont (CM Foz do Iguaçu)/CM Foz do Iguaçu/2018','Caderno Contabilidade Pública Parte 4','Segundo o Manual de Contabilidade Aplicada ao Setor Público (MCASP), avalie as definições utilizadas para a avaliação e mensuração de ativos e passivos, e marque (V) para verdadeiro e (F) para falso: ( ) Valor justo é o valor pelo qual um ativo pode ser intercambiado ou um passivo pode ser liquidado entre partes interessadas que atuam em condições independentes e isentas ou conhecedoras do mercado. ( ) Valor de aquisição é a soma do preço de compra de um bem com os gastos suportados direta ou indiretamente para colocá-lo em condição de uso. ( ) Valor realizável líquido é o valor de mercado de um ativo menos o custo para a sua alienação, ou o valor que a entidade do setor público espera recuperar pelo uso futuro desse ativo nas suas operações, o que for maior. ( ) Valor recuperável é a quantia que a entidade do setor público espera obter com a alienação ou a utilização de itens de inventário quando deduzidos os gastos estimados para seu acabamento, alienação ou utilização. Assinale a alternativa que contém, de cima para baixo, a sequência CORRETA.','[["A","V, F, V, V."],["B","F, V, V, F."],["C","V, V, F, F."],["D","V, V, V, V."]]'::jsonb,'C',2018,624,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — V, V, F, F.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'Segundo o Manual de Contabilidade Aplicada ao Setor Público (MCASP), avalie as definições utilizadas para a avaliação e mensuração de ativos e passivos, e marque (V) para verdadeiro e (F) para falso: ( ) Valor justo é o valor pelo qual um ativo pode ser intercambiado ou um passivo pode ser liquidado entre partes interessadas que atuam em condições independentes e isentas ou con') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2413210',2200,81,'P1','AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público','FAFIPA - Ag (CM Chavantes)/CM Chavantes/Administrativo/2022','Caderno Contabilidade Pública Parte 4','A NBC T 16.2 trata sobre o conceito de Patrimônio Público, a classificação do Patrimônio Público sob o enfoque contábil, o conceito de Sistema Contábil e sua estrutura. Com base nas definições inseridas nesse contexto, analise as afirmativas a seguir e assinale V para a(s) Verdadeira(s) e F para a(s) Falsa(s). ( ) Patrimônio Público é o conjunto de direitos e bens, tangíveis ou intangíveis, onerados ou não, adquiridos, formados, produzidos, recebidos, mantidos ou utilizados pelas entidades do setor público, que seja portador ou represente um fluxo de benefícios, presente ou futuro, inerente à prestação de serviços públicos ou à exploração econômica por entidades do setor público e suas obrigações. ( ) Ativos são recursos controlados pela entidade como resultado de eventos passados e do qual se espera que resultem para a entidade benefícios econômicos futuros ou potencial de serviços. ( ) Passivos são obrigações presentes da entidade, derivadas de eventos futuros, cujos pagamentos se esperam que resultem para a entidade entradas de recursos capazes de gerar benefícios econômicos ou potencial de serviços. ( ) Patrimônio Líquido é o valor residual dos ativos da entidade depois de deduzidos todos seus passivos. Assinale a alternativa com a sequência CORRETA:','[["A","V, V, F, F."],["B","F, V, F, V."],["C","V, V, F, V."],["D","F, F, F, F."],["E","V, V, V, V."]]'::jsonb,'C',2022,625,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — V, V, F, V.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público"}'::jsonb,'A NBC T 16.2 trata sobre o conceito de Patrimônio Público, a classificação do Patrimônio Público sob o enfoque contábil, o conceito de Sistema Contábil e sua estrutura. Com base nas definições inseridas nesse contexto, analise as afirmativas a seguir e assinale V para a(s) Verdadeira(s) e F para a(s) Falsa(s). ( ) Patrimônio Público é o conjunto de direitos e bens, tangíveis ou') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2413211',2201,81,'P1','AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público','FAFIPA - Ag (CM Chavantes)/CM Chavantes/Administrativo/2022','Caderno Contabilidade Pública Parte 4','Segundo a NBC T 16.2, a contabilidade aplicada ao setor público se organiza por meio de sistemas de informações, os quais possuem subsistemas que podem oferecer produtos diferentes em razão da respectiva especificidade e que convergem para o produto final. Dentre os subsistemas, tem-se o (a) que registra, processa e evidencia os atos de gestão cujos efeitos possam produzir modificações no patrimônio da entidade do setor público, bem como aqueles com funções específicas de controle, e o (a) , que registra, processa e evidencia os fatos financeiros e não financeiros relacionados com as variações qualitativas e quantitativas do patrimônio público. Assinale a alternativa que preencha as lacunas CORRETAMENTE:','[["A","patrimonial; orçamentário."],["B","financeiro; custo."],["C","compensação; patrimonial."],["D","orçamentário; custo."],["E","compensação; financeiro."]]'::jsonb,'C',2022,626,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — compensação; patrimonial.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público"}'::jsonb,'Segundo a NBC T 16.2, a contabilidade aplicada ao setor público se organiza por meio de sistemas de informações, os quais possuem subsistemas que podem oferecer produtos diferentes em razão da respectiva especificidade e que convergem para o produto final. Dentre os subsistemas, tem-se o (a) que registra, processa e evidencia os atos de gestão cujos efeitos possam produzir modi') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2413237',2202,81,'P1','AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público','FAFIPA - Ag (CM Chavantes)/CM Chavantes/Administrativo/2022','Caderno Contabilidade Pública Parte 4','De acordo com a NBC T 16.2, o (a) é a característica de transformação de bens e direitos em moeda, e o (a) é a característica inerente às obrigações pelo prazo de vencimento. Nesse sentido, assinale a alternativa que preencha as lacunas CORRETAMENTE:','[["A","Exigibilidade; Não Circulante."],["B","Circulante; Unidade Contábil."],["C","Circulante; Conversibilidade."],["D","Conversibilidade; Exigibilidade."],["E","Unidade Contábil; Circulante"]]'::jsonb,'D',2022,627,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Conversibilidade; Exigibilidade.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público"}'::jsonb,'De acordo com a NBC T 16.2, o (a) é a característica de transformação de bens e direitos em moeda, e o (a) é a característica inerente às obrigações pelo prazo de vencimento. Nesse sentido, assinale a alternativa que preencha as lacunas CORRETAMENTE:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1741406',2203,80,'P1','AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público','FAFIPA - Tec (CM Castro)/CM Castro/Administrativo/2021','Caderno Contabilidade Pública Parte 4','Com base na classificação do patrimônio público sob o enfoque contábil, analise os itens a seguir e assinale a alternativa que apresenta quais estão CORRETOS: I.Conforme a resolução CFC N.º 1.129/08, o Patrimônio Público é estruturado em três grupos (Ativos, Passivos e Patrimônio Líquido). II.Conforme a resolução CFC N.º 1.437/13, os Ativos devem ser classificados como circulante quando tiverem a expectativa de realização até seis meses da data das demonstrações contábeis. III.Conforme a resolução CFC N.º 1.437/13, os Passivos devem ser classificados como circulante quando corresponderem a valores exigíveis até doze meses da data das demonstrações contábeis. IV.Conforme a resolução CFC N.º 1.129/08, os Ativos devem ser classificados como circulante quando estiverem disponíveis para realização imediata.','[["A","Apenas I, III e IV estão corretos."],["B","Apenas II, III e IV estão corretos."],["C","Apenas I e II estão corretos."],["D","Todos estão corretos."],["E","Apenas I, II e III estão corretos."]]'::jsonb,'A',2021,628,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Apenas I, III e IV estão corretos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Patrimônio Público"}'::jsonb,'Com base na classificação do patrimônio público sob o enfoque contábil, analise os itens a seguir e assinale a alternativa que apresenta quais estão CORRETOS: I.Conforme a resolução CFC N.º 1.129/08, o Patrimônio Público é estruturado em três grupos (Ativos, Passivos e Patrimônio Líquido). II.Conforme a resolução CFC N.º 1.437/13, os Ativos devem ser classificados como circulan') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
