INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3876591',2206,76,'P2','AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)','FAFIPA - Ana Cons (COMESP)/COMESP/2026','Caderno Contabilidade Pública Parte 4','De acordo com a Lei de Responsabilidade Fiscal, constitui requisito para a criação, expansão ou aperfeiçoamento de ação governamental que acarrete aumento da despesa:','[["A","apresentar a estimativa do impacto orçamentário-financeiro e a declaração do ordenador de despesas."],["B","demonstrar que o gasto se enquadra no Plano Plurianual (PPA)."],["C","a aprovação expressa do Tribunal de Contas."],["D","apenas a indicação da fonte de recursos."],["E","comprovar que há previsão de receita futura."]]'::jsonb,'A',2026,631,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — apresentar a estimativa do impacto orçamentário-financeiro e a declaração do ordenador de despesas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)"}'::jsonb,'De acordo com a Lei de Responsabilidade Fiscal, constitui requisito para a criação, expansão ou aperfeiçoamento de ação governamental que acarrete aumento da despesa:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3703930',2207,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)','FAFIPA - Adv (CM Candói)/CM Candói/2025','Caderno Contabilidade Pública Parte 4','Preencha as lacunas a seguir e assinale a alternativa com a sequência CORRETA. Para os fins da Lei Complementar nº 101/2000, considera-se __________ com a lei orçamentária anual, a despesa objeto de dotação específica e suficiente, ou que esteja abrangida por crédito genérico, de forma que somadas todas as despesas da mesma espécie, realizadas e a realizar, previstas no programade trabalho, não sejam ultrapassados os limites estabelecidos para o exercício. Já a despesa é__________ com o plano plurianual e a lei de diretrizes orçamentárias, a despesa que se conforme comas diretrizes, objetivos, prioridades e metas previstos nesses instrumentos e não infrinja qualquer desuas disposições.','[["A","Suficiente, incompatível."],["B","Complementar, suficiente."],["C","Compatível, adequada."],["D","Circunstancial, suficiente."],["E","Adequada, compatível."]]'::jsonb,'E',2025,632,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — Adequada, compatível.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)"}'::jsonb,'Preencha as lacunas a seguir e assinale a alternativa com a sequência CORRETA. Para os fins da Lei Complementar nº 101/2000, considera-se __________ com a lei orçamentária anual, a despesa objeto de dotação específica e suficiente, ou que esteja abrangida por crédito genérico, de forma que somadas todas as despesas da mesma espécie, realizadas e a realizar, previstas no program') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1053832',2208,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)','FAFIPA - AAdm (CM Mandaguari)/CM Mandaguari/2019','Caderno Contabilidade Pública Parte 4','De acordo com a Lei Complementar N.º 101/2000, assinale a opção que apresenta a definição CORRETA de despesa obrigatória de caráter continuado:','[["A","Despesa corrente derivada apenas de medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período inferior a três exercícios."],["B","Despesa corrente derivada apenas de ato administrativo normativo que fixem para o ente a obrigação legal de sua execução no exercício em curso."],["C","Despesa atípica derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a quatro exercícios."],["D","Despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios."]]'::jsonb,'D',2019,633,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)"}'::jsonb,'De acordo com a Lei Complementar N.º 101/2000, assinale a opção que apresenta a definição CORRETA de despesa obrigatória de caráter continuado:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
